reactions.activationCode:
const targets = await api.chooseToken(reactorToken, {
    count: 1,
    range: 15,
    title: 'Ushabti Omnigun',
    includeSelf: false
});

if (!targets?.length) return;

await api.executeDamageRoll(reactorToken, targets, '1', 'Kinetic', 'Ushabti Omnigun', { paracausal: true });

reactions.onInit:
async function(token, item, api) {
  await api.addExtraActions(item, [
    { name: 'Cycle Mimic Gun', activation: 'Free', detail: 'Manually cycle to the next range.' }
  ]);
}

reactions.activationCode:
let flags = api.getItemFlags(item) || {};
let x = flags.mimic_x || 1, y = flags.mimic_y || 1, z = flags.mimic_z || 1;
let step = flags.mimic_step || 0;

console.log(triggerData.actionName);
if (triggerData.actionName.includes('Provoke')) {
    const roll = await new Roll('3d20').evaluate({ async: true });
    x = roll.terms[0].results[0].result;
    y = roll.terms[0].results[1].result;
    z = roll.terms[0].results[2].result;
    await roll.toMessage({ 
      speaker: ChatMessage.getSpeaker({ token: reactorToken.document }), 
      flavor: `<b>Provoking Mimic Gun</b><br>Range X: ${x} | Range Y: ${y} | Range Z: ${z}` 
    });
    step = 0;
} else if (triggerData.actionName.includes('Cycle')) {
    step = (step + 1) % 3;
}

await api.addItemFlags(item, { mimic_x: x, mimic_y: y, mimic_z: z, mimic_step: step });

const ranges = [x, y, z];
const currentRange = ranges[step];
const currentDamage = 1 + Math.ceil(currentRange / 2);

const profiles = foundry.utils.duplicate(item.system.profiles);
profiles[0].range = [{ type: 'Range', val: currentRange }];
profiles[0].damage = [{ type: 'Kinetic', val: currentDamage.toString() }];
await item.update({ 'system.profiles': profiles });

ui.notifications.info(`Mimic Gun set to Range ${currentRange}, Damage ${currentDamage}`);

if (triggerType === 'onEnterCombat') {
    await api.executeItemActivation(item, { path: 'system.actions.0' });
} else if (triggerType === 'onTurnStart') {
    if (game.combat && game.combat.round > 1) {
		// proccing the extra action directly didn't work for some reason, so direct repitition of the cycle activation

        let flags = api.getItemFlags(item) || {};
        let x = flags.mimic_x || 1, y = flags.mimic_y || 1, z = flags.mimic_z || 1;

        let step = ((flags.mimic_step || 0) + 1) % 3;
        await api.addItemFlags(item, { mimic_step: step });

        const currentRange = [x, y, z][step];
        const currentDamage = 1 + Math.ceil(currentRange / 2);

        const profiles = foundry.utils.duplicate(item.system.profiles);
        profiles[0].range = [{ type: 'Range', val: currentRange }];
        profiles[0].damage = [{ type: 'Kinetic', val: currentDamage.toString() }];
        await item.update({ 'system.profiles': profiles });

        ui.notifications.info(`Mimic Gun cycled to Range ${currentRange}, Damage ${currentDamage}`);    }
}
